mapper.select:
SELECT LOGIN_ID
FROM `user`
WHERE NAME = #{name}
  AND EMAIL = #{email}
    LIMIT 1

mapper.update:
UPDATE `user`
BIRTH_DATE = #{birthDate}, NICKNAME = #{nickname}, EMAIL = #{email}, PROFILE_IMAGE_URL = #{profileImageUrl}, UPDATED_AT = NOW()
WHERE LOGIN_ID = #{loginId}

mapper.delete:
DELETE FROM `user`
WHERE USER_STATUS = 'DELETED'
  AND DELETED_AT <= #{cutoffDate}

mapper.update:
UPDATE `user`
SET LAST_LOGIN_AT = NOW()
WHERE LOGIN_ID = #{loginId}

UPDATE `user`
SET USER_STATUS = 'DORMANT'
WHERE LOGIN_ID IN (
    SELECT temp.LOGIN_ID FROM (
       SELECT LOGIN_ID
       FROM `user`
       WHERE USER_STATUS = 'ACTIVE'
         AND (
           LAST_LOGIN_AT < #{cutoffDate}
               OR (LAST_LOGIN_AT IS NULL AND CREATED_AT < #{cutoffDate})
           )
   ) AS temp
)

UPDATE `user`
SET USER_STATUS = 'ACTIVE',
    LAST_LOGIN_AT = NOW()
WHERE LOGIN_ID = #{loginId}
  AND EMAIL = #{email}
  AND USER_STATUS = 'DORMANT'

UPDATE `user`
SET USER_STATUS = 'ACTIVE',
    DELETED_AT = NULL,
    LAST_LOGIN_AT = NOW()
WHERE LOGIN_ID = #{loginId}
  AND EMAIL = #{email}
  AND USER_STATUS = 'DELETED'
  AND DELETED_AT > #{cutoffDate}
